// Parser for the generated emoji search index.
//
// The data itself lives in `emojiIndex.txt`, generated by
// `scripts/build-emoji-index.mjs` from Unicode CLDR. This file is hand-written
// and holds only the parse, so the app and the unit tests read the same bytes
// the same way — the tests load the .txt from disk, the app fetches it.
//
// Format, one emoji per line:
//
//   <emoji>\t<name>|<keyword>|<keyword>...
//
// The first field after the tab is the display name; the rest are CLDR search
// keywords. `terms` is every field joined by spaces, which is the single
// lowercase haystack `emojiSearch.js` matches against.

export function parseEmojiIndex(text) {
  const map = new Map()
  if (typeof text !== 'string') return map
  for (const line of text.split('\n')) {
    const tab = line.indexOf('\t')
    if (tab === -1) continue
    const char = line.slice(0, tab)
    const parts = line.slice(tab + 1).split('|')
    if (!char || !parts[0]) continue
    map.set(char, { name: parts[0], terms: parts.join(' ') })
  }
  return map
}
